create table if not exists schedule_planning_relations(id uuid primary key default gen_random_uuid(),institution_code text not null default current_tenant_code(),relation_type text not null,mode text not null default 'HARD' check(mode in('HARD','MEDIUM','SOFT','OFF')),weight numeric not null default 1 check(weight>=0),left_selector jsonb not null default '{}',right_selector jsonb not null default '{}',parameters jsonb not null default '{}',source_type text,source_ref text,effective_from date,effective_to date,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists idx_schedule_planning_relations_tenant on schedule_planning_relations(institution_code,active,relation_type);
alter table schedule_planning_relations enable row level security;
drop policy if exists schedule_planning_relations_read on schedule_planning_relations;create policy schedule_planning_relations_read on schedule_planning_relations for select to authenticated using(tenant_row_allowed(institution_code));
drop policy if exists schedule_planning_relations_manage on schedule_planning_relations;create policy schedule_planning_relations_manage on schedule_planning_relations for all to authenticated using((has_permission('schedule.rules') or is_manager_or_admin()) and tenant_row_allowed(institution_code)) with check((has_permission('schedule.rules') or is_manager_or_admin()) and tenant_row_allowed(institution_code));